"""Authored learning rooms. Facts are public and cited. Toy numbers are labeled."""

from source_catalog import CATALOG

SOURCES = {key: (item["title"], item["url"]) for key, item in CATALOG.items()}


def R(n, title, level, mins, five, idea, ex_title, steps, quiz, cites, terms, actors, flow=None, config=None, trouble=None):
    return {
        "n": n,
        "title": title,
        "level": level,
        "mins": mins,
        "five": five,
        "idea": idea,
        "ex_title": ex_title,
        "steps": steps,
        "quiz": quiz,
        "cites": cites,
        "terms": terms,
        "actors": actors,
        "flow": flow,
        "config": config or ["Write the goal in one sentence.", "Name the input and the allowed output.", "Save the trace next to the result."],
        "trouble": trouble or [("The answer looks fluent and is wrong.", "Check whether a source passage actually contains the claim."), ("The loop never stops.", "Set a step cap and stop when the tool result repeats.")],
    }


